create or replace function private.is_team_member(p_team_id uuid)  
returns boolean  
language sql  
stable  
security definer  
set search_path = ''  
as $$  
select exists (  
select 1  
from public.team_access_memberships m  
join public.profiles p on p.id = m.profile_id  
where m.team_id = p_team_id  
and m.profile_id = auth.uid()  
and m.status = 'ACTIVE'  
and p.active  
and m.valid_from <= now()  
and (m.valid_until is null or m.valid_until > now())  
);  
$$;  

create or replace function private.is_team_coach(p_team_id uuid)  
returns boolean  
language sql  
stable  
security definer  
set search_path = ''  
as $$  
select exists (  
select 1  
from public.team_access_memberships m  
join public.profiles p on p.id = m.profile_id  
where m.team_id = p_team_id  
and m.profile_id = auth.uid()  
and m.role = 'COACH'  
and m.status = 'ACTIVE'  
and p.active  
and m.valid_from <= now()  
and (m.valid_until is null or m.valid_until > now())  
and coalesce(auth.jwt() ->> 'aal', 'aal1') = 'aal2'  
);  
$$;  

create or replace function private.is_own_athlete(p_athlete_id uuid)  
returns boolean  
language sql  
stable  
security definer  
set search_path = ''  
as $$  
select exists (  
select 1 from public.athletes a  
where a.id = p_athlete_id and a.profile_id = auth.uid()  
);  
$$;  

