function gerarLinkPos(e) {
  const answers = {};
  e.response.getItemResponses().forEach(r => answers[r.getItem().getTitle()] = String(r.getResponse() || ''));
  const props = PropertiesService.getScriptProperties();
  const post = FormApp.openById(props.getProperty('POST_FORM_ID'));
  const token = Utilities.getUuid();
  let response = post.createResponse();
  response = addPrefill_(response, post, CEPRAEA.token, token, 'TEXT');
  response = addPrefill_(response, post, CEPRAEA.athlete, answers[CEPRAEA.athlete], 'LIST');
  response = addPrefill_(response, post, CEPRAEA.session, answers[CEPRAEA.session], 'LIST');
  response = addPrefill_(response, post, CEPRAEA.postGoal1, answers[CEPRAEA.goal1], 'PARAGRAPH_TEXT');
  response = addPrefill_(response, post, CEPRAEA.postGoal2, answers[CEPRAEA.goal2], 'PARAGRAPH_TEXT');
  response = addPrefill_(response, post, CEPRAEA.postGoal3, answers[CEPRAEA.goal3], 'PARAGRAPH_TEXT');
  const link = response.toPrefilledUrl();
  const ss = SpreadsheetApp.openById(props.getProperty('RESPONSE_SHEET_ID'));
  const sheet = ensureLinksSheet_(ss);
  sheet.appendRow([token, e.response.getTimestamp(), answers[CEPRAEA.athlete], answers[CEPRAEA.session], answers[CEPRAEA.goal1], answers[CEPRAEA.goal2], answers[CEPRAEA.goal3], link, 'PENDENTE']);
}

function addPrefill_(response, form, title, value, type) {
  const item = form.getItems().find(i => i.getTitle() === title);
  if (!item) throw new Error('Item não encontrado no formulário pós: ' + title);
  if (type === 'LIST') return response.withItemResponse(item.asListItem().createResponse(value));
  if (type === 'PARAGRAPH_TEXT') return response.withItemResponse(item.asParagraphTextItem().createResponse(value));
  return response.withItemResponse(item.asTextItem().createResponse(value));
}

function atualizarListasDosFormularios() {
  const ss = SpreadsheetApp.openById(CEPRAEA.sheetId);
  const props = PropertiesService.getScriptProperties();
  if (!props.getProperty('PRE_FORM_ID') || !props.getProperty('POST_FORM_ID')) return;
  const athletes = getActiveValues_(ss, 'ATLETAS', 2, 4, 5);
  const sessions = getActiveValues_(ss, 'SESSOES', 2, 7, 8);
  [FormApp.openById(props.getProperty('PRE_FORM_ID')), FormApp.openById(props.getProperty('POST_FORM_ID'))].forEach(form => {
    form.getItems().filter(i => i.getType() === FormApp.ItemType.LIST).forEach(item => {
      if (item.getTitle() === CEPRAEA.athlete) item.asListItem().setChoiceValues(athletes);
      if (item.getTitle() === CEPRAEA.session) item.asListItem().setChoiceValues(sessions);
    });
  });
}

function getActiveValues_(ss, sheetName, startRow, valueCol, activeCol) {
  const sheet = ss.getSheetByName(sheetName);
  if (!sheet || sheet.getLastRow() < startRow) return [];
  const data = sheet.getRange(startRow, valueCol, sheet.getLastRow() - startRow + 1, activeCol - valueCol + 1).getDisplayValues();
  return data.filter(r => String(r[activeCol - valueCol]).toUpperCase() === 'SIM' && r[0]).map(r => r[0]);
}

function ensureLinksSheet_(ss) {
  let sheet = ss.getSheetByName('LINKS_POS');
  if (!sheet) sheet = ss.insertSheet('LINKS_POS');
  if (sheet.getLastRow() === 0) {
    sheet.appendRow(['TOKEN', 'DATA_HORA_PRE', 'ATLETA', 'SESSÃO', 'META_TÉCNICA', 'META_TÁTICA', 'META_FÍSICA_MENTAL_COMPORTAMENTAL', 'LINK_PÓS_PERSONALIZADO', 'STATUS_ENVIO']);
    sheet.setFrozenRows(1);
  }
  return sheet;
}

function writeConfig_(ss, key, value) {
  const sheet = ss.getSheetByName('CONFIG');
  const keys = sheet.getRange(1, 1, Math.max(sheet.getLastRow(), 1), 1).getDisplayValues().flat();
  const idx = keys.indexOf(key);
  if (idx >= 0) sheet.getRange(idx + 1, 2).setValue(value);
  else sheet.appendRow([key, value, 'Preenchido automaticamente pelo Apps Script']);
}

### C1.7 Tipos semânticos obrigatórios

Todo item extraído ou criado deverá ser classificado, no mínimo, como um dos 28 tipos semânticos obrigatórios abaixo:

1\. fonte normativa;

2\. fonte regulatória local;

3\. fonte científica;

4\. material técnico;

5\. requisito operacional;

6\. conceito;

7\. entidade candidata;

8\. atributo;

9\. evento;

10\. papel;

11\. estado;

12\. relação;

13\. cardinalidade;

14\. regra;

15\. condição;

16\. exceção;

17\. proibição;

18\. obrigação;

19\. cálculo;

20\. métrica;

21\. evidência;

22\. fato histórico;

23\. hipótese;

24\. decisão;

25\. dúvida;

26\. risco;

27\. controle;

28\. teste.

**Regras de interpretação:**

• regra oficial vigente não é equivalente a evidência científica;

• requisito do PWA não é equivalente a regra oficial da modalidade;

• decisão do treinador não é equivalente a obrigação normativa;

• frequência estatística não é equivalente a prescrição;

• hipótese não é equivalente a decisão validada;

• configuração atual não é equivalente a fato histórico;

• exemplo documental não é automaticamente uma regra geral.

### C2.2 Escopo negativo

Está fora do escopo, salvo mudança formal aprovada:

• criar imediatamente o banco antes dos portões exigidos;

• tratar hipóteses anteriores como modelo aprovado;

• substituir decisão técnica do treinador;

• emitir diagnóstico, prognóstico ou prescrição médica;

• funcionar como sistema oficial completo de arbitragem, federação ou gestão financeira;

• administrar múltiplas modalidades sem autorização;

• transformar resultados científicos em constraints normativas sem fonte competente;

• inserir dados pessoais reais em seeds ou ambientes de teste;

• expor credenciais privilegiadas no PWA;

• alterar produção manualmente sem migration e registro;

• apagar fatos históricos para representar correções;

• ampliar silenciosamente atores, módulos, integrações ou finalidades.

### C4.1 Unidade executável

A unidade executável do plano é a AÇÃO CONTROLADA. Cada ação deverá possuir:

• identificador único no formato ACT-Fxx-nnn;

• nome e objetivo;

• fase e subdomínio;

• tipo semântico do objeto tratado;

• entradas autorizadas;

• precondições;

• dependências;

• procedimento;

• saídas e artefatos;

• evidências obrigatórias;

• testes aplicáveis;

• risco e controles;

• responsável por validação;

• portão relacionado;

• estado atual;

• bloqueios e perguntas abertas;

• próxima ação permitida.

### C4.3 Registro mínimo de riscos e controles

Para cada risco relevante deverá existir pelo menos um controle, uma ação responsável, uma evidência e um teste.

Exemplos obrigatórios:

• SQL prematuro → dependências e portões D/E/F;

• regra revogada → matriz de autoridade e vigência;

• estudo tratado como norma → classificação semântica da fonte;

• hipótese tratada como decisão → máquina de estados;

• dado sensível exposto → classificação, RLS e testes adversariais;

• expansão silenciosa → escopo negativo e controle de mudanças;

• conclusão sem prova → evidência obrigatória e teste de completude.

### C5.2 Transições normais

NÃO\_INICIADO → IDENTIFICADO → PRONTO → EM\_EXECUÇÃO → PRODUZIDO → EM\_REVISÃO → VALIDADO.

Após validação, quando aplicável:

VALIDADO → IMPLEMENTADO → TESTADO → VERIFICADO.

Transições de exceção:

• qualquer estado anterior à validação poderá ir para BLOQUEADO;

• EM\_REVISÃO poderá ir para REJEITADO ou retornar a EM\_EXECUÇÃO;

• item validado substituído por nova versão deverá ir para SUBSTITUÍDO, preservando histórico;

• BLOQUEADO somente poderá sair após registro e resolução da causa.

### C7.1 Tipos de evidência

• referência de fonte e trecho;

• inventário ou contagem reconciliada;

• artefato produzido;

• comparação entre versões;

• decisão humana registrada;

• resultado de consulta ou inspeção;

• resultado de teste positivo ou negativo;

• log de migration ou implantação;

• relatório de advisor, desempenho ou segurança;

• readback que confirme a alteração no destino correto.

### C8.1 Decisões possíveis

APROVADO;

APROVADO\_COM\_RESSALVAS;

REPROVADO;

BLOQUEADO.

## C11. CONDIÇÕES OBRIGATÓRIAS DE PARADA E ESCALONAMENTO

A IA deverá parar e produzir um registro de escalonamento quando ocorrer:

• conflito material entre fontes de mesma autoridade;

• ambiguidade que altere cardinalidade, integridade, segurança ou significado de dado;

• mudança de objetivo ou escopo;

• decisão médica, clínica ou disciplinar fora da competência do sistema;

• decisão sobre dados sensíveis sem regra suficiente;

• operação destrutiva ou alteração de produção sem autorização;

• ausência de evidência para concluir ação crítica;

• inconsistência entre estados, dependências ou portões;

• impossibilidade técnica que comprometa a forma ou a integridade exigida.

O registro de escalonamento deverá conter: problema; contexto; fontes; alternativas; recomendação; impactos; risco de não decidir; autoridade necessária; ação bloqueada.

## C12. CRITÉRIOS DE SUFICIÊNCIA DA MOLDURA

A moldura somente será considerada validada quando uma IA, lendo apenas o CEPRAEA-DB, conseguir responder corretamente:

• qual é o objetivo e o tema;

• qual domínio governa o método;

• qual é o domínio de aplicação;

• quais subdomínios devem ser cobertos;

• o que está dentro e fora do escopo;

• qual fonte ou decisão possui maior autoridade;

• qual é o estado real do projeto;

• qual ação pode ser executada em seguida;

• quais dependências e portões impedem avanço;

• qual evidência prova a conclusão;

• quando deve parar e escalar;

• quando tabelas, SQL, migrations e produção podem ser autorizados.

# 10\. REGISTRO DE DECISÕES E INCERTEZAS

Cada decisão relevante será registrada com:

• identificador;

• questão ou problema;

• fontes consultadas;

• alternativas consideradas;

• decisão adotada;

• justificativa;

• impacto no modelo, PWA, segurança e testes;

• responsável pela validação;

• status e possibilidade de revisão.

Perguntas abertas não serão ocultadas em comentários de SQL; permanecerão em um backlog rastreável até sua resolução.

# 13\. DEFINIÇÃO DE PRONTO DO PLANO COMPLETO

Este plano será considerado cumprido somente quando:

• todas as fontes tiverem status e cobertura documentados;

• todas as decisões de modelagem forem rastreáveis;

• os requisitos do PWA estiverem validados;

• os modelos conceitual, lógico e físico forem aprovados em seus portões;

• as policies e os dados sensíveis estiverem protegidos;

• o banco puder ser recriado por migrations;

• os testes derivados das regras forem executados;

• as jornadas do PWA funcionarem online e offline;

• o desempenho das consultas críticas estiver verificado;

• existirem procedimentos de implantação, rollback, backup e evolução.

# **Premissa obrigatória**

A página 2 não deve ser redesenhada do zero.  
A base deve continuar sendo a **página 2 da versão 0.11**, porque ela já contém:

-   conteúdo correto;
-   logo correta;
-   tabela nominal correta;
-   dirigentes corretos;
-   observação correta;
-   arte lateral correta;
-   fundo branco;
-   identidade institucional coerente.

A próxima versão deve ser feita por **microintervenções locais**, não por reconstrução global.

## **Limitações da ferramenta**

Como estamos trabalhando sobre uma página renderizada em imagem/PDF, a edição não é como em um arquivo vetorial editável com camadas separadas. Isso significa que:

-   mover um bloco pode exigir apagar e redesenhar parte da página;
-   textos podem perder nitidez se forem manipulados como imagem;
-   alterações grandes em tabela e tipografia podem gerar desalinhamentos;
-   a logo e a arte lateral precisam ser aplicadas com cuidado para não parecerem coladas;
-   qualquer reconstrução ampla aumenta risco de mudar nomes, números ou posição dos elementos.

## **Limitações da IA**

A IA pode tentar “melhorar” visualmente e acabar alterando elementos aprovados. O risco principal é:

-   trocar a logo;
-   mudar grafia de nomes;
-   deformar a arte lateral;
-   recriar tabela;
-   alterar proporções;
-   transformar documento institucional em peça promocional;
-   criar uma versão visualmente bonita, mas fora do escopo aprovado.

# **Ordem lógica de implementação**

A implementação deve seguir esta sequência:

1.  cabeçalho;
2.  régua técnica;
3.  espaçamentos verticais;
4.  tabela;
5.  arte lateral;
6.  dirigentes;
7.  observação;
8.  rodapé;
9.  auditoria final.

Essa ordem evita que ajustes no rodapé ou tabela sejam feitos antes de estabilizar o topo da página.

## **Ações**

-   reduzir levemente o título;
-   manter “Relação Nominal” como informação principal;
-   ajustar o subtítulo para parecer subordinado;
-   posicionar a logo à direita com mais respiro;
-   preservar a cor original verde da logo;
-   reduzir a logo cerca de 8% a 12%;
-   alinhar a logo ao eixo óptico do cabeçalho.

## **Riscos**

-   logo voltar para versão errada;
-   logo ficar deformada;
-   título perder força;
-   cabeçalho parecer vazio demais;
-   desalinhamento entre título, subtítulo e logo.

## **Ações**

-   manter os dados em linha única;
-   reduzir contraste dos separadores verticais;
-   deixar rótulos com peso menor;
-   manter valores mais destacados;
-   reduzir a altura da faixa;
-   padronizar linhas superiores e inferiores;
-   usar cinza/roxo discreto, sem excesso.

## **Riscos**

-   informações ficarem pequenas demais;
-   linha técnica perder legibilidade;
-   separadores ficarem fortes demais;
-   texto sair desalinhado.

## **Ações**

-   reduzir o espaço entre cabeçalho e tabela;
-   subir a tabela nominal;
-   subir a arte lateral na mesma proporção;
-   manter a distância entre tabela e arte suficiente para leitura;
-   não alterar conteúdo da tabela;
-   não trocar a arte lateral.

## **Riscos**

-   cortar parte da arte lateral;
-   aproximar demais arte e tabela;
-   criar manchas/resíduos no fundo branco;
-   desalinhamento com dirigentes e observação.

## **Ações**

-   manter todos os nomes exatamente iguais;
-   manter os números exatamente iguais;
-   suavizar linhas internas;
-   melhorar espaçamento interno dos nomes;
-   manter o cabeçalho roxo, porém com acabamento mais limpo;
-   não alterar ordem, largura geral ou estrutura sem necessidade.

## **Riscos**

-   erro de grafia;
-   perda de nitidez;
-   desalinhamento de linhas;
-   tabela ficar diferente da versão aprovada;
-   regressão visual.

## **Ações**

-   manter a mesma arte;
-   mover apenas junto com o corpo;
-   preservar lance completo;
-   manter Roberta e defensora visíveis;
-   evitar que a areia invada a tabela;
-   preservar fundo branco.

## **Riscos**

-   corte nos pés/pernas;
-   areia parecer remendada;
-   defensora sair parcialmente da página;
-   arte ficar colada demais à tabela.

## **Ações**

-   aproximar dirigentes da tabela;
-   reduzir peso visual do bloco;
-   suavizar roxo das células A/B ou diminuir a área preenchida;
-   manter nomes corretos;
-   alinhar com a largura da tabela.

## **Riscos**

-   nomes desalinharem;
-   bloco parecer desconectado;
-   A/B ficarem pequenos demais;
-   criar excesso de espaço à direita.

## **Ações**

-   subir a observação;
-   manter sem box pesado;
-   alinhar com a coluna principal;
-   manter texto integral;
-   usar linha discreta ou recuo lateral;
-   evitar que pareça alerta ou card.

## **Riscos**

-   observação ficar espremida;
-   perder hierarquia;
-   parecer rodapé improvisado;
-   criar desequilíbrio com a arte lateral.

## **Ações**

-   reduzir espaço morto no rodapé;
-   manter linha inferior discreta;
-   evitar duas linhas fortes;
-   se necessário, usar apenas uma linha de fechamento;
-   não adicionar novos elementos sem aprovação.

## **Riscos**

